template <class T>
struct std::hash<std::shared_ptr<T>> {
    std::size_t operator()(const std::shared_ptr<T>& p) const noexcept {
        // Implementation note: This specialization is provided by the standard library.
        // It internally calls std::hash<T*>() on p.get(), which extracts the raw pointer.
        // Compile-time: The template is instantiated here, but the operator() is runtime-executed.
        return std::hash<T*>()(p.get());
    }
};

code_example:
#include <iostream>
#include <unordered_set>
#include <memory>
#include <functional>

int main() {
    auto ptr1 = std::make_shared<int>(42);  // Creates a shared_ptr to an int
    auto ptr2 = ptr1;  // Another shared_ptr pointing to the same int
    auto ptr3 = std::make_shared<int>(42);  // A different shared_ptr to a different int

    std::unordered_set<std::shared_ptr<int>, std::hash<std::shared_ptr<int>>> set;
    set.insert(ptr1);  // Inserts ptr1
    set.insert(ptr2);  // Should not insert, as hash and equality are based on pointer value
    set.insert(ptr3);  // Inserts ptr3, as it points to a different address

    std::cout << "Set size: " << set.size() << std::endl;  // Outputs 2
    return 0;
}
